import numpy as np
from qiskit import QuantumCircuit

def build_oracle(qc: QuantumCircuit, problem_qubits: list[int],
                 ancilla_qubits: list[int]) -> None:
    # constants
    a = [23, 31, 35, 4, 23, 4, 30]
    target = 111
    n_anc = len(ancilla_qubits)  # should be 8

    # ---------- helper functions ----------
    def qft(qubits):
        n = len(qubits)
        for i in reversed(range(n)):
            qc.h(qubits[i])
            for j in range(i - 1, -1, -1):
                angle = np.pi / (2 ** (i - j))
                qc.cp(angle, qubits[i], qubits[j])
        for i in range(n // 2):
            qc.swap(qubits[i], qubits[n - 1 - i])

    def iqft(qubits):
        n = len(qubits)
        for i in range(n // 2):
            qc.swap(qubits[i], qubits[n - 1 - i])
        for i in reversed(range(n)):
            qc.h(qubits[i])
            for j in range(i - 1, -1, -1):
                angle = -np.pi / (2 ** (i - j))
                qc.cp(angle, qubits[i], qubits[j])

    # precompute phase angles for each (problem_qubit, ancilla_qubit) pair
    angles = np.zeros((len(problem_qubits), n_anc), dtype=float)
    for i, val in enumerate(a):
        for k in range(n_anc):
            angle = 2 * np.pi * val * (2 ** k) / (2 ** n_anc)
            angle %= 2 * np.pi
            angles[i][k] = angle

    # ---------- compute sum ----------
    qft(ancilla_qubits)
    for i, pqubit in enumerate(problem_qubits):
        for k, aqubit in enumerate(ancilla_qubits):
            ang = angles[i][k]
            if not np.isclose(ang, 0):
                qc.cp(ang, pqubit, aqubit)
    iqft(ancilla_qubits)

    # ---------- mark target state ----------
    target_bits = [int(b) for b in f"{target:08b}"]  # MSB first
    target_bits = target_bits[::-1]                  # convert to LSB first

    # flip qubits where target bit is 0
    for k, aqubit in enumerate(ancilla_qubits):
        if target_bits[k] == 0:
            qc.x(aqubit)

    # multi‑controlled Z on all ancilla qubits
    target_q = ancilla_qubits[-1]
    controls = ancilla_qubits[:-1]
    qc.h(target_q)
    qc.mcx(controls, target_q, mode='noancilla')
    qc.h(target_q)

    # restore flipped qubits
    for k, aqubit in enumerate(ancilla_qubits):
        if target_bits[k] == 0:
            qc.x(aqubit)

    # ---------- uncompute sum ----------
    qft(ancilla_qubits)
    for i, pqubit in enumerate(problem_qubits):
        for k, aqubit in enumerate(ancilla_qubits):
            ang = angles[i][k]
            if not np.isclose(ang, 0):
                qc.cp(-ang, pqubit, aqubit)
    iqft(ancilla_qubits)
