import math
from qiskit import QuantumCircuit

def apply_qft(qc, qubits, inverse=False):
    n = len(qubits)
    if inverse:
        # inverse QFT: undo swaps, then rotations and H in reverse order
        for i in range(n // 2):
            qc.swap(qubits[i], qubits[n - 1 - i])
        for i in range(n - 1, -1, -1):
            for j in range(n - 1, i, -1):
                angle = -math.pi / (2 ** (j - i))
                qc.cp(angle, qubits[j], qubits[i])
            qc.h(qubits[i])
    else:
        # forward QFT
        for i in range(n):
            qc.h(qubits[i])
            for j in range(i + 1, n):
                angle = math.pi / (2 ** (j - i))
                qc.cp(angle, qubits[j], qubits[i])
        # swap qubits to correct ordering
        for i in range(n // 2):
            qc.swap(qubits[i], qubits[n - 1 - i])


def cond_add(qc, control, target, c, forward=True):
    """Conditionally add constant c to target register using QFT addition."""
    n = len(target)
    if forward:
        apply_qft(qc, target, inverse=False)
        for j in range(n):
            angle = 2 * math.pi * c * (2 ** j) / (2 ** n)
            qc.cp(angle, control, target[j])
        apply_qft(qc, target, inverse=True)
    else:
        # inverse of forward operation
        apply_qft(qc, target, inverse=False)   # first the QFT (adjoint of iQFT)
        for j in reversed(range(n)):
            angle = 2 * math.pi * c * (2 ** j) / (2 ** n)
            qc.cp(-angle, control, target[j])
        apply_qft(qc, target, inverse=True)    # then iQFT


def build_oracle(qc, problem_qubits, ancilla_qubits):
    a = [23, 31, 35, 4, 23, 4, 30]
    target = 111
    n_anc = len(ancilla_qubits)

    # Compute the sum of selected elements into ancilla register
    for i in range(len(problem_qubits)):
        cond_add(qc, problem_qubits[i], ancilla_qubits, a[i], forward=True)

    # Flip bits where target has a 0, so that the state "all ones" corresponds to sum==target
    target_bits = [(target >> j) & 1 for j in range(n_anc)]
    for j in range(n_anc):
        if target_bits[j] == 0:
            qc.x(ancilla_qubits[j])

    # Multi-controlled phase: mark the all‑ones state with a phase of -1
    controls = ancilla_qubits[1:]
    target_qubit = ancilla_qubits[0]
    qc.mcp(math.pi, controls, target_qubit)

    # Undo the X flips
    for j in range(n_anc):
        if target_bits[j] == 0:
            qc.x(ancilla_qubits[j])

    # Uncompute the sum additions in reverse order
    for i in reversed(range(len(problem_qubits))):
        cond_add(qc, problem_qubits[i], ancilla_qubits, a[i], forward=False)
